def getNews(limit=None, cursor=None, language=None, topic_id=None, topic_slug=None, source_id=None, published_after=None, published_before=None, sort=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid_like(prefix):
        # deterministic-enough unique id for logs (not a strict ULID)
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return (False, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string"))
        ss = s.strip()
        # tolerate 'Z'
        try:
            dt = datetime.datetime.fromisoformat(ss.replace("Z", "+00:00"))
        except ValueError:
            return (False, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _load_logs():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        if isinstance(logs, dict) and isinstance(logs.get("rows"), list):
            return logs["rows"]
        return []

    def _save_logs(logs):
        # keep existing shape if file had {"rows":[...]}
        existing = _load("request_logs.json")
        if isinstance(existing, dict):
            existing["rows"] = logs
            _save("request_logs.json", existing)
        else:
            _save("request_logs.json", logs)

    def _record_log(status, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": _ulid_like("nfs_req"),
            "ts": _now_iso(),
            "endpoint": "getNews",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save_logs(logs)

    def _enforce_rate_limit():
        # Best-effort: 120 requests/minute per endpoint globally if logs exist.
        logs = _load_logs()
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "getNews":
                continue
            ts = r.get("ts") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                n += 1
        if n >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _record_log("rejected", "RATE_LIMIT")
        return rl

    # Validate inputs
    server_max = 50
    if limit is None:
        limit = server_max
    if not isinstance(limit, int):
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.", minimum=1, maximum=100)
    if limit < 1 or limit > 100:
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit is out of range.", minimum=1, maximum=100)
    if limit > server_max:
        limit = server_max

    allowed_lang = {"en","zh","ja","ko","es","fr","de","pt","ru","tr","vi","id","th","other"}
    if language is not None:
        if not isinstance(language, str) or language not in allowed_lang:
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid language.", allowed=sorted(list(allowed_lang)))

    if topic_id is not None:
        if not isinstance(topic_id, str) or not re.match(r"^nfs_tpc_[0-9A-HJKMNP-TV-Z]{26}$", topic_id):
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid topic_id.")
    if source_id is not None:
        if not isinstance(source_id, str) or not re.match(r"^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$", source_id):
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid source_id.")

    if topic_slug is not None:
        if not isinstance(topic_slug, str) or not topic_slug.strip():
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "topic_slug must be a non-empty string.")

    pa = _parse_dt(published_after, "published_after")
    if isinstance(pa, tuple) and pa and pa[0] is False:
        _record_log("rejected", "VALIDATION_ERROR")
        return pa[1]
    pb = _parse_dt(published_before, "published_before")
    if isinstance(pb, tuple) and pb and pb[0] is False:
        _record_log("rejected", "VALIDATION_ERROR")
        return pb[1]
    if pa is not None and pb is not None and pa > pb:
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "published_after must be <= published_before.")

    allowed_sort = {"published_at_desc","published_at_asc","importance_desc"}
    if sort is None:
        sort = "published_at_desc"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", allowed=sorted(list(allowed_sort)))

    # Cursor: accept opaque string; only our own base64 JSON is interpreted. Otherwise treat as "start".
    cursor_payload = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_payload = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_payload, dict):
                cursor_payload = None
        except Exception:
            cursor_payload = None

    # Resolve topic filter
    topics = _load("topics.json")
    if isinstance(topics, dict) and isinstance(topics.get("rows"), list):
        topics = topics["rows"]
    if not isinstance(topics, list):
        topics = []

    topic_row = None
    if topic_id is not None:
        for t in topics:
            if isinstance(t, dict) and t.get("id") == topic_id:
                topic_row = t
                break
        if topic_row is None:
            _record_log("ok")
            return {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
    if topic_slug is not None and topic_row is None:
        slug_l = topic_slug.strip().lower()
        for t in topics:
            if isinstance(t, dict) and isinstance(t.get("slug"), str) and t.get("slug").lower() == slug_l:
                topic_row = t
                break
        if topic_row is None:
            _record_log("ok")
            return {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

    topic_filter_id = topic_row.get("id") if isinstance(topic_row, dict) else None

    # If topic filter active, load join table to get allowed content_item_ids
    allowed_item_ids = None
    if topic_filter_id is not None:
        cit = _load("content_item_topics.json")
        if isinstance(cit, dict) and isinstance(cit.get("rows"), list):
            cit = cit["rows"]
        if not isinstance(cit, list):
            cit = []
        allowed_item_ids = set()
        for r in cit:
            if not isinstance(r, dict):
                continue
            if r.get("topic_id") == topic_filter_id and isinstance(r.get("content_item_id"), str):
                allowed_item_ids.add(r["content_item_id"])
        if not allowed_item_ids:
            _record_log("ok")
            return {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

    # Load content items and apply base filters
    items = _load("content_items.json")
    if isinstance(items, dict) and isinstance(items.get("rows"), list):
        items = items["rows"]
    if not isinstance(items, list):
        items = []

    def _dt_for_sort(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    filtered = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("content_type") != "news_flash":
            continue
        if it.get("status") != "published":
            continue
        if it.get("duplicate_of_item_id") is not None:
            continue
        if language is not None and it.get("language") != language:
            continue
        if source_id is not None and it.get("source_id") != source_id:
            continue
        if allowed_item_ids is not None and it.get("id") not in allowed_item_ids:
            continue

        pub_dt = _dt_for_sort(it.get("published_at"))
        if pa is not None:
            if pub_dt is None:
                continue
            if pub_dt <= pa:
                continue
        if pb is not None:
            if pub_dt is None:
                continue
            if pub_dt >= pb:
                continue
        filtered.append(it)

    # Sorting with stable chronological ordering
    def _sort_key(it):
        pub = _dt_for_sort(it.get("published_at"))
        ing = _dt_for_sort(it.get("ingested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        pub_rank = pub if pub is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        imp = it.get("importance_score")
        if not isinstance(imp, (int, float)):
            imp = 0.0
        # For NULLS LAST in desc, we can use (has_pub, pub) with has_pub False first then reverse, or just map None to min and track flag.
        has_pub = 1 if pub is not None else 0

        if sort == "published_at_desc":
            return (has_pub, pub_rank, ing, str(it.get("id") or ""))
        if sort == "published_at_asc":
            # NULLS LAST: use has_pub first, then pub asc, ing asc
            return (0 if has_pub else 1, pub_rank, ing, str(it.get("id") or ""))
        # importance_desc: keep chronological ordering stable for equal timestamps
        return (has_pub, pub_rank, ing, imp, str(it.get("id") or ""))

    reverse = True
    if sort == "published_at_asc":
        reverse = False
    elif sort == "importance_desc":
        reverse = True

    # For importance_desc we want importance descending but within same timestamps stable.
    if sort == "importance_desc":
        def _sort_key_imp(it):
            pub = _dt_for_sort(it.get("published_at"))
            ing = _dt_for_sort(it.get("ingested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            pub_rank = pub if pub is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            has_pub = 1 if pub is not None else 0
            imp = it.get("importance_score")
            if not isinstance(imp, (int, float)):
                imp = 0.0
            return (has_pub, pub_rank, ing, imp, str(it.get("id") or ""))
        filtered.sort(key=_sort_key_imp, reverse=True)
    else:
        filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)

    # Apply cursor as "start after" marker if it matches.
    start_idx = 0
    if isinstance(cursor_payload, dict) and cursor_payload.get("after_id"):
        after_id = cursor_payload.get("after_id")
        if isinstance(after_id, str):
            for i, it in enumerate(filtered):
                if it.get("id") == after_id:
                    start_idx = i + 1
                    break

    page = filtered[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < total
    next_cursor = None
    if has_more and page:
        payload = {"after_id": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _record_log("ok", meta={"returned": len(page), "total": total})
    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

