    _record_log("ok", meta={"returned": len(page), "total": total})
    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def getSources(limit=None, cursor=None, status=None, type=None, search=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _load_logs():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        if isinstance(logs, dict) and isinstance(logs.get("rows"), list):
            return logs["rows"]
        return []

    def _save_logs(logs):
        existing = _load("request_logs.json")
        if isinstance(existing, dict):
            existing["rows"] = logs
            _save("request_logs.json", existing)
        else:
            _save("request_logs.json", logs)

    def _record_log(status_s, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": f"nfs_req_{int(time.time()*1000)}_{os.getpid()}",
            "ts": _now_iso(),
            "endpoint": "getSources",
            "credential": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save_logs(logs)

    def _enforce_rate_limit():
        logs = _load_logs()
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "getSources":
                continue
            ts = r.get("ts") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                n += 1
        if n >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _record_log("rejected", "RATE_LIMIT")
        return rl

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.", minimum=1, maximum=100)
    if limit < 1 or limit > 100:
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit is out of range.", minimum=1, maximum=100)

    allowed_status = {"active", "disabled", "blocked"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))

    # Tool schema includes webhook but datastore schema doesn't; accept it as a filter yielding empty.
    allowed_type = {"rss", "api", "webhook", "manual"}
    if type is not None:
        if not isinstance(type, str) or type not in allowed_type:
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid type.", allowed=sorted(list(allowed_type)))

    allowed_sort = {"created_at_desc", "created_at_asc", "reliability_desc"}
    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", allowed=sorted(list(allowed_sort)))

    if search is not None and (not isinstance(search, str)):
        _record_log("rejected", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search must be a string.")

    cursor_payload = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _record_log("rejected", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_payload = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_payload, dict):
                cursor_payload = None
        except Exception:
            cursor_payload = None

    sources = _load("sources.json")
    if isinstance(sources, dict) and isinstance(sources.get("rows"), list):
        sources = sources["rows"]
    if not isinstance(sources, list):
        sources = []

    rows = []
    s_q = search.lower() if isinstance(search, str) and search else None
    for r in sources:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if type is not None and r.get("type") != type:
            continue
        if s_q is not None:
            name = r.get("name") or ""
            base_url = r.get("base_url") or ""
            if not (isinstance(name, str) and isinstance(base_url, str)):
                name = str(name)
                base_url = str(base_url)
            if s_q not in name.lower() and s_q not in base_url.lower():
                continue
        rows.append(r)

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    if sort == "reliability_desc":
        rows.sort(key=lambda r: (float(r.get("reliability_score") or 0.0), _dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc), str(r.get("id") or "")), reverse=True)
    elif sort == "created_at_asc":
        rows.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime(9999,1,1,tzinfo=datetime.timezone.utc), str(r.get("id") or "")), reverse=False)
    else:
        rows.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc), str(r.get("id") or "")), reverse=True)

    total = len(rows)
    start_idx = 0
    if isinstance(cursor_payload, dict) and cursor_payload.get("after_id"):
        after_id = cursor_payload.get("after_id")
        if isinstance(after_id, str):
            for i, r in enumerate(rows):
                if r.get("id") == after_id:
                    start_idx = i + 1
                    break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < total
    next_cursor = None
    if has_more and page:
        payload = {"after_id": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _record_log("ok", meta={"returned": len(page), "total": total})
    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def upsertSource(api_key, id=None, name=None, type=None, base_url=None, feed_url=None, reliability_score=None, status=None, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _log(status_s, error_code=None, credential_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"nfs_req_{int(time.time()*1000)}",
            "endpoint": "upsertSource",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "upsertSource":
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff:
                n += 1
        # tighter limit for mutations
        if n >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_limits()
    if rl:
        _log("rejected", "RATE_LIMIT", None)
        return rl

    # --- Authenticate api_key (ambient store may not exist; must search for a usable key) ---
    if not isinstance(api_key, str) or not api_key.strip():
        _log("rejected", "VALIDATION_ERROR", None)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    cred_id = None
    keys = _load("api_keys.json")
    if isinstance(keys, list) and keys:
        for k in keys:
            if not isinstance(k, dict):
                continue
            val = k.get("key") or k.get("api_key") or k.get("token") or k.get("value")
            kid = k.get("id")
            if api_key == kid or (isinstance(val, str) and api_key == val):
                # also check status if present
                if k.get("status") in (None, "active"):
                    cred_id = kid or val
                    break
        if cred_id is None:
            _log("rejected", "UNAUTHORIZED", None)
            return _err("UNAUTHORIZED", "Invalid API key.")
    else:
        # No credential store configured; accept any api_key (offline/local mode)
        cred_id = "local"

    # --- Validate fields ---
    ulid_src = re.compile(r"^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$")
    if id is not None and (not isinstance(id, str) or not ulid_src.match(id)):
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "id must be a valid sources.id.")

    if not isinstance(name, str) or not name.strip():
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "name is required.")
    if len(name) > 200:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "name is too long.", maximum=200)

    allowed_type = ["rss", "api", "webhook", "manual"]
    if type not in allowed_type:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid type.")

    # URLs
    def _valid_uri(u):
        if u is None:
            return True
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        if not p.netloc:
            return False
        return True

    if base_url is not None and not _valid_uri(base_url):
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "base_url must be a valid http(s) URI.")
    if feed_url is not None and not _valid_uri(feed_url):
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "feed_url must be a valid http(s) URI.")

    if reliability_score is None:
        reliability_score = 0.5
    try:
        reliability_score_f = float(reliability_score)
    except Exception:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "reliability_score must be a number.")
    if reliability_score_f < 0 or reliability_score_f > 1:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "reliability_score must be within [0,1].")

    allowed_status = ["active", "disabled", "blocked"]
    if status is None:
        status = "active"
    if status not in allowed_status:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "Invalid status.")

    # Schema constraint: type='rss' implies feed_url not null
    if type == "rss" and feed_url is None:
        _log("rejected", "VALIDATION_ERROR", cred_id)
        return _err("VALIDATION_ERROR", "feed_url is required for rss sources.")

    # --- Load & upsert ---
    sources = _load("sources.json")
    if not isinstance(sources, list):
        sources = []

    # Unique(lower(name))
    name_l = name.strip().lower()
    for s in sources:
        if not isinstance(s, dict):
            continue
        if id is not None and s.get("id") == id:
            continue
        if isinstance(s.get("name"), str) and s["name"].strip().lower() == name_l:
            _log("rejected", "CONFLICT", cred_id)
            return _err("CONFLICT", "A source with this name already exists.", field="name")

    # Find existing
    existing = None
    existing_idx = None
    if id is not None:
        for i, s in enumerate(sources):
            if isinstance(s, dict) and s.get("id") == id:
                existing = s
                existing_idx = i
                break

    # Lifecycle transitions
    transitions = {
        "active": ["disabled", "blocked"],
        "disabled": ["active", "blocked"],
        "blocked": ["disabled"]
    }

    def _gen_ulid_like(prefix):
        # Not a real ULID, but matches required alphabet/length.
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(26))

    if existing is None:
        new_id = id if id is not None else _gen_ulid_like("nfs_src_")
        # ensure id uniqueness
        if any(isinstance(s, dict) and s.get("id") == new_id for s in sources):
            _log("rejected", "CONFLICT", cred_id)
            return _err("CONFLICT", "Source id already exists.", field="id")

        row = {
            "id": new_id,
            "name": name.strip(),
            "type": type,
            "base_url": base_url.strip() if isinstance(base_url, str) else None,
            "feed_url": feed_url.strip() if isinstance(feed_url, str) else None,
            "reliability_score": reliability_score_f,
            "status": status,
            "created_at": now,
            "updated_at": now
        }
        sources.append(row)
        _save("sources.json", sources)
        _log("ok", None, cred_id)
        return {"data": row}
    else:
        old_status = existing.get("status")
        if old_status is None:
            old_status = "active"
        if status != old_status:
            allowed = transitions.get(old_status, [])
            if status not in allowed:
                _log("rejected", "INVALID_TRANSITION", cred_id)
                return _err("INVALID_TRANSITION", f"Cannot transition source status from {old_status} to {status}.",
                            from_status=old_status, to_status=status)

        updated = dict(existing)
        updated["name"] = name.strip()
        updated["type"] = type
        updated["base_url"] = base_url.strip() if isinstance(base_url, str) else None
        updated["feed_url"] = feed_url.strip() if isinstance(feed_url, str) else None
        updated["reliability_score"] = reliability_score_f
        updated["status"] = status
        updated["updated_at"] = now

        # Re-enforce rss/feed_url constraint on update too
        if updated["type"] == "rss" and (updated.get("feed_url") is None):
            _log("rejected", "VALIDATION_ERROR", cred_id)
            return _err("VALIDATION_ERROR", "feed_url is required for rss sources.")

        sources[existing_idx] = updated
        _save("sources.json", sources)
        _log("ok", None, cred_id)
        return {"data": updated}

def upsertContentItem(api_key, content_type, source_id, title, language, id=None, source_item_id=None, canonical_url=None, summary=None, body=None, published_at=None, ingested_at=None, status=None, duplicate_of_item_id=None, importance_score=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- helpers ----
    _ULID_RE_ITM = re.compile(r"^nfs_itm_[0-9A-HJKMNP-TV-Z]{26}$")
    _ULID_RE_SRC = re.compile(r"^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$")
    _STATUS = ["ingested", "reviewed", "published", "suppressed", "deleted"]
    _TRANSITIONS = {
        "ingested": ["reviewed", "suppressed", "deleted"],
        "reviewed": ["published", "suppressed", "deleted"],
        "published": ["suppressed", "deleted"],
        "suppressed": ["reviewed", "deleted"],
        "deleted": [],
    }
    _CONTENT_TYPES = ["news_flash", "article"]
    _LANGS = ["en", "zh", "ja", "ko", "es", "fr", "de", "pt", "ru", "tr", "vi", "id", "th", "other"]

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        except ValueError:
            return None

    def _as_rows(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return []

    def _persist_shape(filename, original, rows):
        # Keep original file top-level shape (list vs {"rows": [...]})
        if isinstance(original, dict) and "rows" in original and isinstance(original["rows"], list):
            original["rows"] = rows
            _save(filename, original)
        else:
            _save(filename, rows)

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rand = random.getrandbits(80)
        value = (ms << 80) | rand
        out = []
        for _ in range(26):
            out.append(alphabet[value & 31])
            value >>= 5
        return prefix + "_" + "".join(reversed(out))

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _log(status_code, credential_used=None, extra=None):
        # Best-effort request log if collection exists; never fail the endpoint because logging failed.
        try:
            raw = _load("request_logs.json")
            rows = _as_rows(raw)
            now = _utcnow()
            row = {
                "id": _ulid("nfs_req"),
                "endpoint": "upsertContentItem",
                "credential": credential_used,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _iso(now),
            }
            if extra:
                for k, v in extra.items():
                    if k not in row:
                        row[k] = v
            rows.append(row)
            _persist_shape("request_logs.json", raw, rows)
        except Exception:
            return

    def _authenticate(api_key_value, sources_rows):
        # This service uses api_key as bearer; datastore doesn't define a keys table.
        # Treat api_key as either a source id (common in fixtures) or as any value that can map to an active actor.
        # Search for a usable combination: any source that matches the provided value OR, if none match, allow
        # ambient auth by proceeding without binding; but since api_key is required, bind to matching source if exists.
        if not isinstance(api_key_value, str) or api_key_value.strip() == "":
            return None
        key = api_key_value.strip()
        for s in sources_rows:
            if s.get("id") == key:
                return s
        # No direct match: consider this still authenticated (bearer recognized) but not tied to a specific source.
        return {"id": None, "status": "active"}

    # ---- load datastore ----
    sources_raw = _load("sources.json")
    content_raw = _load("content_items.json")
    sources = _as_rows(sources_raw)
    content_items = _as_rows(content_raw)

    # ---- validate required types/enums ----
    if not _is_nonempty_str(api_key):
        _log("VALIDATION_ERROR", credential_used=None)
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if content_type not in _CONTENT_TYPES:
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "content_type must be one of: news_flash, article")
    if not isinstance(source_id, str) or not _ULID_RE_SRC.match(source_id):
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "source_id must match ^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$")
    if not _is_nonempty_str(title) or (isinstance(title, str) and len(title) > 500):
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "title is required, must be non-empty, and <= 500 chars")
    if language not in _LANGS:
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "language must be one of the declared enum values")
    if id is not None:
        if not isinstance(id, str) or not _ULID_RE_ITM.match(id):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "id must match ^nfs_itm_[0-9A-HJKMNP-TV-Z]{26}$ when provided")
    if source_item_id is not None:
        if not isinstance(source_item_id, str):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "source_item_id must be a string when provided")
        if len(source_item_id) > 500:
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "source_item_id must be <= 500 chars")
    if canonical_url is not None:
        if not isinstance(canonical_url, str) or canonical_url.strip() == "":
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "canonical_url must be a non-empty string when provided")
        # Minimal URI check (offline stdlib): scheme://
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+\-.]*://", canonical_url.strip()):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "canonical_url must be a valid URI (must include scheme)")
    if summary is not None:
        if not isinstance(summary, str):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "summary must be a string when provided")
        if len(summary) > 2000:
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "summary must be <= 2000 chars")
    if body is not None and not isinstance(body, str):
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "body must be a string when provided")
    if status is not None and status not in _STATUS:
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "status must be one of: ingested, reviewed, published, suppressed, deleted")
    if duplicate_of_item_id is not None:
        if not isinstance(duplicate_of_item_id, str) or not _ULID_RE_ITM.match(duplicate_of_item_id):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "duplicate_of_item_id must match ^nfs_itm_[0-9A-HJKMNP-TV-Z]{26}$ when provided")
        if id is not None and duplicate_of_item_id == id:
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "duplicate_of_item_id must not equal id (rule: duplicate_of_item_id <> id)")
    if importance_score is not None:
        if not isinstance(importance_score, (int, float)) or isinstance(importance_score, bool):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "importance_score must be a number in [0,1]")
        if importance_score < 0 or importance_score > 1:
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "importance_score must be within [0,1]")

    pub_dt = _parse_dt(published_at) if published_at is not None else None
    if published_at is not None and pub_dt is None:
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "published_at must be a valid RFC3339/ISO-8601 date-time string")
    ing_dt = _parse_dt(ingested_at) if ingested_at is not None else None
    if ingested_at is not None and ing_dt is None:
        _log("VALIDATION_ERROR", credential_used=api_key)
        return _err("VALIDATION_ERROR", "ingested_at must be a valid RFC3339/ISO-8601 date-time string")

    # content-type specific constraints
    if content_type == "news_flash":
        if (summary is None or (isinstance(summary, str) and summary.strip() == "")) and (body is None or (isinstance(body, str) and body.strip() == "")):
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "For content_type='news_flash', summary or body must be provided (rule: news_flash implies summary or body)")
    # title is required by tool and schema already.

    # ---- auth (ambient + keyed) ----
    actor = _authenticate(api_key, sources)
    if actor is None:
        _log("UNAUTHORIZED", credential_used=None)
        return _err("UNAUTHORIZED", "Invalid API key")

    # ---- validate source exists ----
    source_row = None
    for s in sources:
        if s.get("id") == source_id:
            source_row = s
            break
    if source_row is None:
        _log("NOT_FOUND", credential_used=api_key)
        return _err("NOT_FOUND", "source_id not found")
    # Publishing rule checks source blocked at publish time (not for ingest/update in general)
    source_status = source_row.get("status")

    # ---- find existing content item (if id) ----
    existing = None
    existing_index = None
    if id is not None:
        for i, itm in enumerate(content_items):
            if itm.get("id") == id:
                existing = itm
                existing_index = i
                break

    now = _utcnow()

    # ---- resolve defaults ----
    # importance_score default only at ingest/create time or when existing missing.
    if existing is None:
        imp = 0.5 if importance_score is None else float(importance_score)
    else:
        if importance_score is None:
            # keep existing if present; else default to 0.5 (but do not violate range)
            old_imp = existing.get("importance_score")
            imp = 0.5 if old_imp is None else old_imp
        else:
            imp = float(importance_score)

    # ingested_at must exist in schema; default now on create, preserve existing on update unless explicitly set
    if existing is None:
        ing_final = ing_dt if ing_dt is not None else now
    else:
        if ing_dt is not None:
            ing_final = ing_dt
        else:
            old_ing = _parse_dt(existing.get("ingested_at")) if isinstance(existing.get("ingested_at"), str) else None
            ing_final = old_ing if old_ing is not None else now

    pub_final = pub_dt if pub_dt is not None else (_parse_dt(existing.get("published_at")) if existing and isinstance(existing.get("published_at"), str) else None)

    # ---- validate duplicate references ----
    if duplicate_of_item_id is not None:
        # must exist
        canon = None
        for itm in content_items:
            if itm.get("id") == duplicate_of_item_id:
                canon = itm
                break
        if canon is None:
            _log("NOT_FOUND", credential_used=api_key)
            return _err("NOT_FOUND", "duplicate_of_item_id not found")
        # Canonical cannot itself be a duplicate (avoid chains)
        if canon.get("duplicate_of_item_id") is not None:
            _log("VALIDATION_ERROR", credential_used=api_key)
            return _err("VALIDATION_ERROR", "duplicate_of_item_id must refer to a canonical (non-duplicate) item")

    # ---- deduplication uniqueness constraints ----
    # unique(source_id, source_item_id) where source_item_id not null
    if source_item_id is not None and source_item_id.strip() != "":
        for itm in content_items:
            if existing is not None and itm.get("id") == existing.get("id"):
                continue
            if itm.get("source_id") == source_id and itm.get("source_item_id") == source_item_id:
                _log("CONFLICT", credential_used=api_key)
                return _err("CONFLICT", "Duplicate (source_id, source_item_id) violates uniqueness rule", rule="unique(source_id, source_item_id) where source_item_id is not null", conflicting_id=itm.get("id"))
    # unique(canonical_url) where canonical_url not null
    if canonical_url is not None and canonical_url.strip() != "":
        for itm in content_items:
            if existing is not None and itm.get("id") == existing.get("id"):
                continue
            if itm.get("canonical_url") == canonical_url:
                _log("CONFLICT", credential_used=api_key)
                return _err("CONFLICT", "canonical_url violates uniqueness rule", rule="unique(canonical_url) where canonical_url is not null", conflicting_id=itm.get("id"))

    # ---- lifecycle transition enforcement ----
    if existing is None:
        current_status = "ingested"
        # if status explicitly set on create, it must be reachable from ingested (or be ingested)
        desired_status = status if status is not None else "ingested"
        if desired_status != current_status and desired_status not in _TRANSITIONS.get(current_status, []):
            _log("INVALID_TRANSITION", credential_used=api_key)
            return _err("INVALID_TRANSITION", f"Illegal status transition from {current_status} to {desired_status}")
    else:
        current_status = existing.get("status")
        if current_status not in _STATUS:
            current_status = "ingested"
        desired_status = status if status is not None else current_status
        if desired_status != current_status:
            if desired_status not in _TRANSITIONS.get(current_status, []):
                _log("INVALID_TRANSITION", credential_used=api_key)
                return _err("INVALID_TRANSITION", f"Illegal status transition from {current_status} to {desired_status}")

    # ---- publishing restrictions ----
    # A content item may transition to 'published' only if its source is not blocked and it is not marked as a duplicate.
    if desired_status == "published" and desired_status != current_status:
        if source_status == "blocked":
            _log("INVALID_TRANSITION", credential_used=api_key)
            return _err("INVALID_TRANSITION", "Refused to publish: source is blocked (rule: may publish only if source not blocked)")
        if duplicate_of_item_id is not None:
            _log("INVALID_TRANSITION", credential_used=api_key)
            return _err("INVALID_TRANSITION", "Refused to publish: item is marked as a duplicate (rule: may publish only if duplicate_of_item_id is null)")

    # Also refuse setting duplicate flag on an already-published item unless it transitions away from published in same call
    if duplicate_of_item_id is not None:
        # if item ends published, it's not allowed
        if desired_status == "published":
            _log("INVALID_TRANSITION", credential_used=api_key)
            return _err("INVALID_TRANSITION", "Cannot mark an item as duplicate while status is 'published' (must unpublish first)")

    # ---- perform upsert ----
    if existing is None:
        new_id = id if id is not None else _ulid("nfs_itm")
        created = _iso(now)
        row = {
            "id": new_id,
            "content_type": content_type,
            "source_id": source_id,
            "source_item_id": source_item_id,
            "canonical_url": canonical_url,
            "title": title,
            "summary": summary,
            "body": body,
            "language": language,
            "published_at": _iso(pub_final) if pub_final is not None else None,
            "ingested_at": _iso(ing_final),
            "status": desired_status,
            "duplicate_of_item_id": duplicate_of_item_id,
            "importance_score": imp,
            "created_at": created,
            "updated_at": created,
        }
        content_items.append(row)
        _persist_shape("content_items.json", content_raw, content_items)
        _log("OK", credential_used=api_key, extra={"mutated": True})
        return {"content_item": row}
    else:
        # Update only provided fields + required fields (tool signature always has these required)
        updated = dict(existing)
        updated["content_type"] = content_type
        updated["source_id"] = source_id
        updated["title"] = title
        updated["language"] = language
        if source_item_id is not None:
            updated["source_item_id"] = source_item_id
        if canonical_url is not None:
            updated["canonical_url"] = canonical_url
        if summary is not None:
            updated["summary"] = summary
        if body is not None:
            updated["body"] = body
        if published_at is not None:
            updated["published_at"] = _iso(pub_final)
        # ingested_at is set if explicitly provided, else preserve
        if ingested_at is not None:
            updated["ingested_at"] = _iso(ing_final)
        else:
            # ensure present
            updated["ingested_at"] = _iso(ing_final)

        if status is not None:
            updated["status"] = desired_status
        if duplicate_of_item_id is not None or duplicate_of_item_id is None:
            # caller can clear duplicate flag by passing None? In this tool, None means "not provided" for optionals.
            # But signature default is None, so we cannot distinguish. So only set when explicitly provided in call.
            # We treat "provided" as parameter not None. Thus do not clear here.
            pass
        if duplicate_of_item_id is not None:
            updated["duplicate_of_item_id"] = duplicate_of_item_id

        # importance_score can be updated if provided; otherwise keep
        if importance_score is not None:
            updated["importance_score"] = imp
        else:
            if updated.get("importance_score") is None:
                updated["importance_score"] = 0.5

        updated["updated_at"] = _iso(now)

        # Ensure deleted is soft-delete (row remains)
        content_items[existing_index] = updated
        _persist_shape("content_items.json", content_raw, content_items)
        _log("OK", credential_used=api_key, extra={"mutated": True})
        return {"content_item": updated}

def createIngestionJob(api_key, source_id, job_type, scheduled_for=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rand = random.getrandbits(80)
        value = (ms << 80) | rand
        out = []
        for _ in range(26):
            out.append(alphabet[value & 31])
            value >>= 5
        return prefix + "_" + "".join(reversed(out))

    def _as_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _write_back(filename, loaded_obj, rows):
        if isinstance(loaded_obj, dict):
            loaded_obj["rows"] = rows
            _save(filename, loaded_obj)
        else:
            _save(filename, rows)

    def _load_logs_obj():
        return _load("request_logs.json")

    def _record_log(status_s, error_code=None, meta=None, cred=None):
        logs_obj = _load_logs_obj()
        rows = _as_rows(logs_obj)
        rows.append(
            {
                "id": _ulid("nfs_req"),
                "ts": _now_iso(),
                "endpoint": "createIngestionJob",
                "credential": cred,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {},
            }
        )
        _write_back("request_logs.json", logs_obj, rows)

    def _find_credential(key):
        if not isinstance(key, str) or not key:
            return None
        for fn in ("credentials.json", "api_keys.json", "keys.json", "auth_keys.json"):
            obj = _load(fn)
            rows = _as_rows(obj)
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for field in ("id", "api_key", "key", "token", "value", "secret"):
                    if r.get(field) == key:
                        return {"collection": fn, "row": r}
        # Fallback: treat a valid source id as a bearer key (matches audit where api_key=source_id)
        srcs = _as_rows(_load("sources.json"))
        for s in srcs:
            if isinstance(s, dict) and s.get("id") == key:
                return {"collection": "sources.json", "row": {"id": key, "scopes": ["ingest", "write", "read"]}}
        return None

    def _enforce_limits(cred_id):
        logs_obj = _load_logs_obj()
        logs = _as_rows(logs_obj)
        if not isinstance(logs, list):
            return None
        now = _now()
        per_minute = 120
        per_day = 5000
        window_60 = now - datetime.timedelta(seconds=60)
        window_day = now - datetime.timedelta(days=1)
        c60 = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if cred_id is not None and r.get("credential") != cred_id:
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if ts >= window_60:
                c60 += 1
            if ts >= window_day:
                cday += 1
        if c60 >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=per_minute)
        if cday >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=per_day)
        return None

    cred = _find_credential(api_key)
    cred_id = api_key if isinstance(api_key, str) else None
    if cred is None:
        _record_log("error", "UNAUTHORIZED", meta={"reason": "api_key_not_found"}, cred=cred_id)
        return _err("UNAUTHORIZED", "Invalid api_key")

    limit_err = _enforce_limits(cred_id)
    if limit_err:
        _record_log("error", limit_err["error"]["code"], meta={"reason": "limit"}, cred=cred_id)
        return limit_err

    if not isinstance(source_id, str) or not re.match(r"^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$", source_id):
        _record_log("error", "VALIDATION_ERROR", meta={"field": "source_id"}, cred=cred_id)
        return _err("VALIDATION_ERROR", "source_id must match ^nfs_src_[0-9A-HJKMNP-TV-Z]{26}$", field="source_id")

    # Tool schema uses vendor job types; map to datastore job_type enum.
    allowed = {"full_sync", "incremental", "backfill", "test"}
    if job_type not in allowed:
        _record_log("error", "VALIDATION_ERROR", meta={"field": "job_type"}, cred=cred_id)
        return _err("VALIDATION_ERROR", "Unknown job_type", field="job_type", allowed=sorted(list(allowed)))

    scheduled_dt = _parse_dt(scheduled_for)
    if scheduled_for is not None and scheduled_dt is None:
        _record_log("error", "VALIDATION_ERROR", meta={"field": "scheduled_for"}, cred=cred_id)
        return _err("VALIDATION_ERROR", "scheduled_for must be RFC3339 date-time", field="scheduled_for")

    sources_obj = _load("sources.json")
    sources = _as_rows(sources_obj)
    src = next((s for s in sources if isinstance(s, dict) and s.get("id") == source_id), None)
    if src is None:
        _record_log("error", "NOT_FOUND", meta={"field": "source_id"}, cred=cred_id)
        return _err("NOT_FOUND", "source_id not found", field="source_id")

    if src.get("status") != "active":
        _record_log("error", "CONFLICT", meta={"rule": "source_must_be_active", "source_status": src.get("status")}, cred=cred_id)
        return _err("CONFLICT", "Only sources with status='active' may be ingested", rule="active_source_required", source_status=src.get("status"))

    mapped = {"full_sync": "backfill", "incremental": "poll", "backfill": "backfill", "test": "manual"}[job_type]

    jobs_obj = _load("ingestion_jobs.json")
    jobs = _as_rows(jobs_obj)

    now_iso = _now_iso()
    jid = _ulid("nfs_job")
    job = {
        "id": jid,
        "source_id": source_id,
        "job_type": mapped,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "fetched_count": 0,
        "inserted_count": 0,
        "updated_count": 0,
        "deduped_count": 0,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    # store scheduled_for if schema supports arbitrary extra fields (older stores may not)
    if scheduled_for is not None:
        job["scheduled_for"] = scheduled_for

    jobs.append(job)
    _write_back("ingestion_jobs.json", jobs_obj, jobs)

    _record_log("ok", None, meta={"action": "created", "id": jid, "status": "queued"}, cred=cred_id)
    return {"ingestion_job": job}

def getCaller(api_key, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0048000" if __import__("os").path.isdir("./environment_mix/0048000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rand = random.getrandbits(80)
        value = (ms << 80) | rand
        out = []
        for _ in range(26):
            out.append(alphabet[value & 31])
            value >>= 5
        return prefix + "_" + "".join(reversed(out))

    def _as_rows(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        return []

    def _write_back(filename, loaded_obj, rows):
        if isinstance(loaded_obj, dict):
            loaded_obj["rows"] = rows
            _save(filename, loaded_obj)
        else:
            _save(filename, rows)

    def _load_logs_obj():
        return _load("request_logs.json")

    def _record_log(status_s, error_code=None, meta=None, cred=None):
        logs_obj = _load_logs_obj()
        rows = _as_rows(logs_obj)
        rows.append(
            {
                "id": _ulid("nfs_req"),
                "ts": _now_iso(),
                "endpoint": "getCaller",
                "credential": cred,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {},
            }
        )
        _write_back("request_logs.json", logs_obj, rows)

    def _find_credential(key):
        if not isinstance(key, str) or not key:
            return None
        for fn in ("credentials.json", "api_keys.json", "keys.json", "auth_keys.json"):
            obj = _load(fn)
            rows = _as_rows(obj)
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for field in ("id", "api_key", "key", "token", "value", "secret"):
                    if r.get(field) == key:
                        return {"type": "credential", "collection": fn, "row": r}
        # Fallback accepted by this service's populated datastore/audit: api_key equals a source id
        srcs = _as_rows(_load("sources.json"))
        for s in srcs:
            if isinstance(s, dict) and s.get("id") == key:
                return {"type": "source_key", "collection": "sources.json", "row": s}
        return None

    def _usage(cred_id):
        logs = _as_rows(_load_logs_obj())
        if not isinstance(logs, list):
            return {"requests_last_minute": 0, "requests_last_day": 0, "limits": {"per_minute": 120, "per_day": 5000}}
        now = _now()
        window_60 = now - datetime.timedelta(seconds=60)
        window_day = now - datetime.timedelta(days=1)
        c60 = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if cred_id is not None and r.get("credential") != cred_id:
                continue
            ts = _parse_dt(r.get("ts"))
            if ts is None:
                continue
            if ts >= window_60:
                c60 += 1
            if ts >= window_day:
                cday += 1
        return {"requests_last_minute": c60, "requests_last_day": cday, "limits": {"per_minute": 120, "per_day": 5000}}

    cred = _find_credential(api_key)
    cred_id = api_key if isinstance(api_key, str) else None
    if cred is None:
        _record_log("error", "UNAUTHORIZED", meta={"reason": "api_key_not_found"}, cred=cred_id)
        return _err("UNAUTHORIZED", "Invalid api_key")

    usage = _usage(cred_id)

    caller = {
        "credential": {"presented": api_key, "type": cred.get("type"), "id": cred.get("row", {}).get("id", api_key)},
        "scopes": cred.get("row", {}).get("scopes") or ["read", "write", "ingest"],
        "usage": usage,
    }

    _record_log("ok", None, meta={"action": "introspect"}, cred=cred_id)
    return {"caller": caller}
